<?php
namespace Database\Seeders;use Illuminate\Database\Seeder;use Spatie\Permission\Models\{Permission,Role};use Spatie\Permission\PermissionRegistrar;
class RolePermissionSeeder extends Seeder{public function run():void{app(PermissionRegistrar::class)->forgetCachedPermissions();$resources=['dashboard'=>['view'],'users'=>['view','create','edit','delete'],'accounts'=>['view','create','edit','delete'],'user-types'=>['view','create','edit','delete'],'companies'=>['view','create','edit','delete'],'addresses'=>['view','create','edit','delete'],'contacts'=>['view','create','edit','delete'],'education'=>['view','create','edit','delete'],'roles'=>['view','create','edit','delete'],'permissions'=>['view','create','edit','delete'],'modules'=>['view','create','edit','delete'],'theme-settings'=>['view','edit'],'action-logs'=>['view'],'api-integrations'=>['view','create','edit','delete']];foreach($resources as $resource=>$actions)foreach($actions as $action)Permission::firstOrCreate(['name'=>"$resource.$action",'guard_name'=>'web']);$super=Role::firstOrCreate(['name'=>'Super Admin','guard_name'=>'web']);$super->syncPermissions(Permission::all());$admin=Role::firstOrCreate(['name'=>'Admin','guard_name'=>'web']);$admin->syncPermissions(Permission::whereNotIn('name',['roles.delete','permissions.delete'])->get());$viewer=Role::firstOrCreate(['name'=>'Viewer','guard_name'=>'web']);$viewer->syncPermissions(Permission::where('name','like','%.view')->get());}}
